import {PageBannerOutlet} from '@github-ui/page-banner'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {getQueryClient} from '@github-ui/react-core/query-client'
import {ShieldLockIcon} from '@primer/octicons-react'
import {PageHeader, Stack, UnderlineNav} from '@primer/react'
import {useCallback, useState} from 'react'

import {AddCustomKeyButton} from '../../components/AddCustomKeyButton'
import {ApiKeys} from '../../components/ApiKeys'
import {AvailableModels} from '../../components/AvailableModels'
import {CurrentOrgProvider} from '../../contexts/CurrentOrgContext'
import type {CustomModelsIndexTabs} from '../../types'
import {customModelsIndexRoute} from './custom-models-index-route'

export function CustomModelsIndex() {
  const {data} = useRouteQuery(customModelsIndexRoute, 'mainQuery')

  const hasKeys = data.customKeys.length > 0

  return (
    <CurrentOrgProvider value={data.orgDisplayLogin}>
      <PageBannerOutlet />
      <Stack gap="spacious">
        <PageHeader hasBorder>
          <PageHeader.TitleArea>
            <PageHeader.Title as="h2" className="text-normal">
              Custom models
            </PageHeader.Title>
          </PageHeader.TitleArea>
          {hasKeys && (
            <PageHeader.Actions>
              <AddCustomKeyButtonShowRoute />
            </PageHeader.Actions>
          )}
        </PageHeader>
        <p className="mb-0">
          Add API keys from AI model providers to register custom third-party models. Once added, you can enable custom
          models to be used with specific GitHub features.
        </p>
        <p>
          When using these models, GitHub will share your data, including code, with the third-party model provider
          using your provided API key. Use of the model is further subject to the terms and privacy policy of the
          third-party model provider.
        </p>
        {data.enabled ? <CustomKeysTabs /> : <EnterpriseDisabledMessage />}
      </Stack>
    </CurrentOrgProvider>
  )
}

function CustomKeysTabs() {
  const {
    data: {customModels, customKeys, publicKey},
    queryKey,
  } = useRouteQuery(customModelsIndexRoute, 'mainQuery')

  const [selectedTab, setSelectedTab] = useState<CustomModelsIndexTabs>('keys')

  const customModelsCount = customModels.length
  const keyCount = customKeys.length

  const ariaCurrent = (tab: CustomModelsIndexTabs): {'aria-current'?: 'page'} =>
    selectedTab === tab ? {'aria-current': 'page'} : {}

  const onRefresh = useCallback(() => {
    void getQueryClient().invalidateQueries({queryKey})
  }, [queryKey])

  return (
    <div className="border rounded-2 overflow-hidden">
      <UnderlineNav aria-label="Custom models navigation">
        <UnderlineNav.Item
          onClick={() => setSelectedTab('keys')}
          counter={keyCount}
          as="button"
          {...ariaCurrent('keys')}
        >
          API keys
        </UnderlineNav.Item>
        <UnderlineNav.Item
          onClick={() => setSelectedTab('models')}
          counter={customModelsCount}
          as="button"
          {...ariaCurrent('models')}
        >
          Custom models
        </UnderlineNav.Item>
      </UnderlineNav>
      <Stack gap="none">
        {selectedTab === 'keys' ? (
          <ApiKeys customKeys={customKeys} publicKey={publicKey[1]} onRefresh={onRefresh} />
        ) : (
          <AvailableModels
            customKeys={customKeys}
            publicKey={publicKey[1]}
            customModels={customModels}
            onUpdateModels={onRefresh}
          />
        )}
      </Stack>
    </div>
  )
}

function AddCustomKeyButtonShowRoute() {
  const {
    data: {publicKey},
    queryKey,
  } = useRouteQuery(customModelsIndexRoute, 'mainQuery')

  const onSuccess = useCallback(() => {
    void getQueryClient().invalidateQueries({queryKey})
  }, [queryKey])

  return <AddCustomKeyButton onSuccess={onSuccess} publicKey={publicKey[1]} />
}

function EnterpriseDisabledMessage() {
  return (
    <div className="border rounded-2 tmp-p-3 tmp-mb-3">
      <ShieldLockIcon className="v-align-middle mr-1" />
      <span className="mb-0">Custom models have been disabled by your enterprise policy administrators.</span>
    </div>
  )
}
