import type {Provider} from '@github-ui/models-byok/providers'
import {getQueryClient} from '@github-ui/react-core/query-client'
import {produce} from 'immer'
import {useEffect, useMemo} from 'react'

import {isValidModelId} from '../../helpers/model-id-schema'
import {useFetchProviderModels} from '../../hooks/use-fetch-provider-models'
import type {SelectorCustomModel} from '../../types'
import {ModelSelectorPane} from '../ModelSelectorPane'
import type {ProviderFieldProps} from './types'

type ProviderModelSelectorPaneProps<P extends Provider = Provider> = ProviderFieldProps<P> & {
  provider: P
  htmlForId?: string
  'aria-describedby'?: string
  customKeyId?: number
  deploymentUrl?: string
}

export function ProviderModelSelectorPane({
  provider,
  customKeyId,
  deploymentUrl,
  apiKey,
  isPending: disabled,
  htmlForId,
  'aria-describedby': ariaDescribedBy,
  onSetAdditionalData,
  canAddModels,
  setValidation,
}: ProviderModelSelectorPaneProps) {
  // If we have a customKey, always fetch models
  //   and if not, only fetch if we have an apiKey
  const shouldLoadModels = customKeyId != null || !!apiKey
  const {
    error,
    data: models,
    isError,
    isFetching,
    queryKey,
  } = useFetchProviderModels({apiKey, provider, customKeyId, deploymentUrl, enabled: shouldLoadModels})

  const selectedModels = useMemo(() => {
    return new Set(models.flatMap(m => (m.selected ? [m.slug] : [])))
  }, [models])

  function onSelect(selected: boolean, model: SelectorCustomModel) {
    getQueryClient().setQueryData<SelectorCustomModel[]>(
      queryKey,
      produce(prev => {
        if (!prev) return prev
        const maybeModel = prev.find(m => m.slug === model.slug)
        if (maybeModel) {
          maybeModel.selected = selected
        }
      }),
    )
  }

  function onLabelUpdate(newLabel: string, model: SelectorCustomModel) {
    getQueryClient().setQueryData<SelectorCustomModel[]>(
      queryKey,
      produce(prev => {
        if (!prev) return prev
        const maybeModel = prev.find(m => m.slug === model.slug)
        if (maybeModel) {
          maybeModel.name = newLabel === '' ? undefined : newLabel
        }
      }),
    )
  }

  function onAddModel(slug: string) {
    const isValidModelSlug = isValidModelId(slug)
    if (isValidModelSlug != null) return isValidModelSlug

    getQueryClient().setQueryData<SelectorCustomModel[]>(
      queryKey,
      produce(prev => {
        if (!prev) return prev
        const newModel: SelectorCustomModel = {
          slug,
          selected: true,
        }
        prev.push(newModel)
        return prev
      }),
    )
  }

  useEffect(() => {
    onSetAdditionalData({models: models.filter(m => selectedModels.has(m.slug))})
  }, [models, selectedModels, onSetAdditionalData])

  useEffect(() => {
    if (error) {
      setValidation({api_key: {error: error.message}})
    } else {
      setValidation(undefined)
    }
  }, [error, isError, setValidation])

  return (
    <ModelSelectorPane
      models={models}
      selected={selectedModels}
      loading={isFetching}
      onSelect={onSelect}
      onLabelUpdate={onLabelUpdate}
      disabled={disabled}
      htmlForId={htmlForId}
      aria-describedby={ariaDescribedBy}
      create={canAddModels}
      onCreate={onAddModel}
      editable
    />
  )
}
