import {string} from 'zod/v4'

export const modelIDSchema = string().refine(value => /^[a-zA-Z0-9._-]{2,64}$/.test(value), {
  message:
    'Model ID must be alphanumeric, can include underscores, hyphens, and periods, and be between 2 and 64 characters long',
})

export function isValidModelId(modelId: string): string | undefined {
  return modelIDSchema.safeParse(modelId).error?.issues[0]?.message
}
